From 63fc1063d151ca99509a05b6c3c71cb2517d707e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:09:44 +0100
Subject: [PATCH] runners/recentdocuments: skip files that no longer exist

The runner keeps its activity stats model across queries, so a file that
was renamed or deleted after it was opened kept being offered under Recent
Files and failed to open. Skip results whose file no longer exists.

BUG: 506792
---
 runners/recentdocuments/recentdocuments.cpp | 7 ++++++-
 1 file changed, 6 insertions(+), 1 deletion(-)

diff --git a/runners/recentdocuments/recentdocuments.cpp b/runners/recentdocuments/recentdocuments.cpp
index 7fd702dd6a..97a351ea38 100644
--- a/runners/recentdocuments/recentdocuments.cpp
+++ b/runners/recentdocuments/recentdocuments.cpp
@@ -70,6 +70,11 @@ void RecentDocuments::match(KRunner::RunnerContext &context)
             continue; // A previous result or a result where the path, but not filename matches
         }

+        const QString path = m_resultsModel->data(index, ResultModel::ResourceRole).toString();
+        if (!QFileInfo::exists(path)) {
+            continue; // The file was moved or deleted since it was last used
+        }
+
         KRunner::QueryMatch match(this);
         // We know the term starts with the query, check size to see if it is an exact match
         if (term.size() >= 5 && indexOfTerm == 0 && (fileName.size() == term.size() || QFileInfo(fileName).baseName().size() == term.size())) {
@@ -84,7 +89,7 @@ void RecentDocuments::match(KRunner::RunnerContext &context)
         }
         const QMimeType mimeType = db.mimeTypeForName(m_resultsModel->data(index, ResultModel::MimeType).toString());
         match.setIconName(mimeType.iconName());
-        const QUrl url = QUrl::fromLocalFile(m_resultsModel->data(index, ResultModel::ResourceRole).toString());
+        const QUrl url = QUrl::fromLocalFile(path);
         match.setUrls({url});
         if (mimeType.isValid() && !mimeType.isDefault()) {
             match.setData(mimeType.name());
-- 
